interface ContainerProps {
  maxWidth?: 'sm' | 'md' | 'lg' | 'xl' | 'full';
  padding?: boolean;
  center?: boolean;
  className?: string;
  children: React.ReactNode;
}

const maxWidthMap = {
  sm: '640px',
  md: '768px',
  lg: '1024px',
  xl: '1280px',
  full: '100%',
};

function Container({
  maxWidth = 'lg',
  padding = true,
  center = true,
  className,
  children,
}: ContainerProps) {
  return (
    <div
      className={cn('container', className)}
      style={{
        maxWidth: maxWidthMap[maxWidth],
        marginLeft: center ? 'auto' : undefined,
        marginRight: center ? 'auto' : undefined,
        paddingLeft: padding ? '1rem' : undefined,
        paddingRight: padding ? '1rem' : undefined,
      }}
    >
      {children}
    </div>
  );
}

// Compose layouts freely
<Page>
  <Container maxWidth="xl">
    <Stack gap="lg">
      <Hero />
      <Section>
        <Container maxWidth="md">
          <Article />
        </Container>
      </Section>
    </Stack>
  </Container>
</Page>

type Direction = 'row' | 'column' | 'row-reverse' | 'column-reverse';

type StackProps = {
  direction?: Direction;
  gap?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  align?: 'start' | 'center' | 'end' | 'stretch';
  justify?: 'start' | 'center' | 'end' | 'between';
  wrap?: boolean;
  children: React.ReactNode;
};

const gapMap = { xs: '0.25rem', sm: '0.5rem', md: '1rem', lg: '1.5rem', xl: '2rem' };

function Stack({
  direction = 'column',
  gap = 'md',
  align = 'stretch',
  justify = 'start',
  wrap = false,
  children,
}: StackProps) {
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: direction,
        gap: gapMap[gap],
        alignItems: align,
        justifyContent: justify === 'between' ? 'space-between' : justify,
        flexWrap: wrap ? 'wrap' : 'nowrap',
      }}
    >
      {children}
    </div>
  );
}

// Usage
<Stack direction="column" gap="lg">
  <Card title="First" />
  <Card title="Second" />
  <Card title="Third" />
</Stack>

interface GridProps {
  columns?: number;
  gap?: number;
  children: React.ReactNode;
}

function Grid({ columns = 3, gap = 16, children }: GridProps) {
  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
        gap,
      }}
    >
      {React.Children.map(children, (child, index) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            'data-grid-index': index,
            className: cn(child.props.className, 'grid-item'),
          });
        }
        return child;
      })}
    </div>
  );
}

// Usage
<Grid columns={3} gap={24}>
  <Card title="A" />
  <Card title="B" />
  <Card title="C" />
</Grid>

